INSERT INTO public.regulation_articles (id, chapter_id, code, title, content, content_type, sort_order) VALUES
('chuong-i-dieu-6', 'qcdgxl-chuong-i', 'chuong-i-dieu-6', 'Điều 6. Mức đánh giá, xếp loại chất lượng', 'Cán bộ, viên chức, người lao động được đánh giá, xếp loại chất lượng theo 4 mức:

a) Hoàn thành xuất sắc nhiệm vụ (Loại A1);', 'text', 6),
('chuong-ii-dieu-7', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-7', 'Điều 7. Thẩm quyền đánh giá, xếp loại chất lượng', '- UBND tỉnh xếp loại đối với Giám đốc, Phó Giám đốc trên cơ sở nhận xét, đánh giá của Hội đồng thi đua khen thưởng, đánh giá, xếp loại Ban QLDA.

- Hội đồng thi đua khen thưởng, đánh giá, xếp loại Ban QLDA xem xét, quyết định kết quả đánh giá, xếp loại viên chức, người lao động; tổ chức nhận xét, đánh giá xếp loại các trưởng phòng, tập thể các phòng; nhận xét, đánh giá Giám đốc, Phó Giám đốc, tập thể Ban QLDA làm cơ sở đề xuất UBND tỉnh xếp loại.

- Trưởng phòng đánh giá, xếp loại hàng tháng đối với phó phòng, viên chức và người lao động thuộc đơn vị.

- Cán bộ, viên chức, người lao động tự đánh giá, xếp loại hàng tháng đối với bản thân.', 'text', 1),
('chuong-ii-dieu-8', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-8', 'Điều 8. Tiêu chí đánh giá, xếp loại (Thang điểm 100\)', '1. Ý thức tổ chức kỷ luật, phẩm chất đạo đức lối sống **(tối đa 20 điểm)**

- Ý thức tổ chức kỷ luật; phẩm chất đạo đức, lối sống, tác phong, lề lối làm việc chuẩn mực **(tối đa 6 điểm).**

- Đoàn kết, thực hiện nguyên tắc tập trung dân chủ trong cơ quan **(tối đa 5 điểm).**

- Thực hiện hiện nghiêm quy tắc ứng xử trong các hoạt động của cơ quan **(tối đa 3 điểm).**

- Thực hiện nghiêm quy định văn hóa công sở, đạo đức công vụ của viên chức, người lao động **(tối đa 6 điểm).**

2. Kết quả thực hiện chức trách nhiệm vụ được giao **(tối đa 75 điểm)**

a) Năng lực và kỹ năng **(tối đa 20 điểm)**', 'text', 2),
('chuong-ii-dieu-9', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-9', 'Điều 9. Mức xếp loại', '1. Đối với cán bộ, viên chức, người lao động:

- Hoàn thành xuất sắc nhiệm vụ (xếp loại A1): Đạt từ 91 đến 100 điểm.

- Hoàn thành tốt nhiệm vụ (xếp loại A): Đạt từ 71 đến dưới 90 điểm.

- Hoàn thành nhiệm vụ (xếp loại B): Đạt từ 50 đến dưới 70 điểm.

- Không hoàn thành nhiệm vụ (xếp loại C): Dưới 50 điểm.', 'text', 3),
('chuong-ii-dieu-10', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-10', 'Điều 10. Một số trường hợp cụ thể trong đánh giá, xếp loại', '1. Không đánh giá, xếp loại trong tháng với cán bộ, viên chức, người lao động trong thời gian ký hợp đồng thử việc; nghỉ thai sản; nghỉ ốm, nghỉ do bị tai nạn lao động quá 20/22 ngày làm việc trong tháng; nghỉ việc riêng không hưởng lương quá 15/22 ngày làm việc trong tháng (kể cả nghỉ phép).

2. Đối với cán bộ, viên chức, người lao động có thời gian nghỉ việc từ trên 12 ngày làm việc trong tháng vì lý do ốm đau... thì mức xếp loại của tháng tối đa là hoàn thành nhiệm vụ (xếp loại B).

3. Đối với trường hợp cán bộ, viên chức, người lao động được cử đi đào tạo, bồi dưỡng (hệ không tập trung) mà thời gian làm việc thực tế trong tháng chưa đạt trên 50% số ngày làm việc của tháng thì vẫn thực hiện đánh giá nhưng mức xếp loại tối đa là hoàn thành nhiệm vụ (xếp loại B).

4. Đối với trường hợp viên chức, người lao động được cử đi học tập trung, thoát ly công việc cơ quan trên 30 ngày/năm làm việc thì căn cứ vào kết quả học tập để đánh giá, mức xếp loại tối đa là hoàn thành tốt nhiệm vụ (xếp loại A).

Trường hợp khi chưa có kết quả học tập, tạm thời xếp loại A và khi có kết quả học tập sẽ điều chỉnh xếp loại (Kết quả học tập đạt loại giỏi, loại khá thì xếp loại A; đạt loại trung bình thì xếp loại B; kết quả học tập dưới trung bình hoặc không hoàn thành khóa học thì xếp loại C).

5. Đối với cán bộ, viên chức, người lao động chịu trách nhiệm chính trong xử lý công việc trong tháng khi có văn bản phê bình của cơ quan cấp trên thì mức xếp loại của tháng tối đa là hoàn thành nhiệm vụ (xếp loại B); Lãnh đạo của phòng đó bị hạ 1 bậc xếp loại trong tháng.

6. Trường hợp xếp loại ở mức khác do Giám đốc Ban QLDA xem xét, đánh giá và quyết định.', 'text', 4),
('chuong-ii-dieu-11', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-11', 'Điều 11. Quy trình, các bước thực hiện đánh giá, xếp loại', 'Trên cơ sở chức năng nhiệm vụ của đơn vị, khuyến khích Lãnh đạo phòng xây dựng, sửa đổi, bổ sung, điều chỉnh Phiếu đánh giá, xếp loại hàng tháng dành cho cán bộ lãnh đạo quản lý; Phiếu đánh giá, xếp loại hàng tháng dành cho viên chức, người lao động đảm bảo phù hợp, sát với thực tế công tác chuyên môn của đơn vị nhằm đánh giá, xếp loại chính xác, khách quan, công bằng, đúng thực chất gắn với kết quả công tác chuyên môn của từng cá nhân.

- Bước 1: Viên chức, người lao động tự kiểm điểm, nhận mức xếp loại hàng tháng.

- Bước 2: Các phòng chuyên môn tổ chức nhận xét, đánh giá xếp loại viên chức, người lao động hàng tháng trên cơ sở tự xếp loại của các cá nhân. Tiến hành bỏ phiếu kín xếp loại để khẳng định sự tín nhiệm tại cuộc họp chuyên môn của phòng sau lễ chào cờ hàng tháng.

- Bước 3: Gửi kết quả xếp loại hàng tháng đến bộ phận tổng hợp thuộc phòng Hành chính - Tổng hợp trước 10h00 ngày 05 của tháng kế tiếp. Hồ sơ gồm: (i) Biên bản họp đánh giá, xếp loại của phòng; (ii) Danh sách tổng hợp kết quả đánh giá, xếp loại đối với viên chức, người lao động.

- Bước 4: Trên cơ sở kết quả đánh giá, xếp loại hàng tháng, Phòng Hành chính - Tổng hợp kiểm tra, rà soát, tham mưu, tổng hợp kết quả đánh giá, xếp loại trình Hội đồng thi đua, khen thưởng, đánh giá, xếp loại Ban QLDA.

- Bước 5: Ban Giám đốc tổ chức kiểm điểm, tự đánh giá, xếp loại các đ/c trong Ban Giám đốc; Hội đồng thi đua, khen thưởng, đánh giá, xếp loại Ban QLDA xem xét, quyết định kết quả đánh giá, xếp loại của Phó phòng, viên chức, người lao động; tổ chức nhận xét, đánh giá xếp loại các đ/c trong Ban giám đốc; các đ/c trưởng phòng; tập thể các phòng; tập thể Ban QLDA (bằng hình thức bỏ phiếu kín để khẳng định sự tín nhiệm). Mức xếp loại của các đ/c trong Ban giám đốc và lãnh đạo các phòng không cao hơn kết quả xếp loại của đơn vị mình được giao quản lý, phụ trách.

- Bước 6: Công khai kết đánh giá, xếp loại viên chức, người lao động tại Hội nghi viên chức và người lao động hoặc mạng thông tin nội bộ của cơ quan.

Các vấn đề khiếu nại về công tác đánh giá, xếp loại sẽ do Giám đốc Ban QLDA xem xét, quyết định theo quy định về phân cấp quản lý cán bộ.', 'text', 5),
('chuong-ii-dieu-12', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-12', 'Điều 12. Khiếu nại, kiến nghị về kết quả xếp loại chất lượng.', '1. Khi có cơ sở cho rằng kết quả xếp loại chất lượng không đúng quy định của pháp luật hoặc quy chế đánh giá của đơn vị, viên chức có quyền kiến nghị về kết quả xếp loại chất lượng đối với mình bằng văn bản đến Giám đốc Ban QLDA. Văn bản kiến nghị phải nêu rõ căn cứ kiến nghị, nội dung kiến nghị và đề xuất.

2. Thời hạn kiến nghị là 05 ngày kể từ ngày công khai kết quả xếp loại chất lượng.

3. Cấp có thẩm quyền có trách nhiệm giải quyết kiến nghị bằng hình thức đối thoại hoặc bằng văn bản trong thời hạn 10 ngày làm việc kể từ ngày nhận được kiến nghị.

4. Trình tự, thủ tục giải quyết kiến nghị về kết quả xếp loại chất lượng thực hiện theo quy định tại Điều này và theo quy chế của đơn vị. Không xem xét lại kết quả giải quyết kiến nghị.', 'text', 6),
('chuong-ii-dieu-13', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-13', 'Điều 13. Sử dụng kết quả đánh giá, xếp loại hàng tháng để đánh giá xếp loại đối với cán bộ, viên chức, người lao động hằng năm.', 'Kết quả đánh giá xếp loại cả năm là kết quả của các tháng được xếp loại chia cho 12 tháng (tổng số điểm của các tháng xếp loại trong năm/12).', 'text', 7),
('chuong-ii-dieu-14', 'qcdgxl-chuong-ii', 'chuong-ii-dieu-14', 'Điều 14. Biểu mẫu', '- Phụ lục 01: Phiếu đánh giá, xếp loại hàng tháng dành cho viên chức lãnh đạo, quản lý.

- Phụ lục 02: Phiếu đánh giá, xếp loại hàng tháng dành cho viên chức, người lao động.

- Phụ lục 03: Biên bản họp đánh giá, xếp loại hàng tháng của phòng chuyên môn.

- Phụ lục 04: Bảng tổng hợp kết quả đánh giá, xếp loại đối với cán bộ, viên chức, người lao động của phòng chuyên môn.

- Phụ lục 05: Bảng tổng hợp, rà soát kết quả đánh giá, xếp loại.

- Phụ lục 06: Báo cáo kết quả thực hiện nhiệm vụ và kế hoạch tháng …

- Phụ lục 07: Báo cáo tiến độ xử lý văn bản trên Hệ thống quản lý hồ sơ công việc; xử lý hồ sơ qua Bộ phận một cửa,

- Phụ lục 08: Báo cáo chấp hành kỷ luật, kỷ cương hành chính;.

#', 'text', 8),
('chuong-iii-dieu-15', 'qcdgxl-chuong-iii', 'chuong-iii-dieu-15', 'Điều 15. Trách nhiệm của viên chức, người lao động', '1. Thực hiện nghiêm các quy định về đánh giá, xếp loại viên chức, người lao động. Phản ánh kịp thời việc thực hiện đánh giá, xếp loại tại các phòng chuyên môn chưa đúng hoặc chưa nghiêm túc với Ban Giám đốc Ban QLDA tỉnh.

2. Được quyền bảo lưu ý kiến về kết quả đánh giá, xếp loại hàng tháng của mình và có quyền phản ánh với Lãnh đạo Ban QLDA trong trường hợp không đồng ý với quyết định mức xếp loại đối với bản thân, nhưng phải chấp hành kết luận, nhận xét, đánh giá của cấp có thẩm quyền.

3. Xây dựng kế hoạch thực hiện hàng tháng, quý, cả năm; báo cáo kết quả thực hiện trong tháng. Nộp kế hoạch năm trong quý I; kế hoạch tháng trước ngày 05 của tháng; báo cáo kết quả thực hiện trong tháng trước ngày 25 hàng tháng qua Lãnh đạo phòng để tập hợp gửi phòng Kế hoạch - Đâu thầu tổng hợp, tham mưu báo cáo Ban QLDA.', 'text', 1)
